sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          // Add your code here
	var str0 = '<p style="margin: 0cm 0cm 8pt; line-height: 107%; font-size: 11pt; font-family: Calibri, sans-serif;"><img style="margin: 0px 10px 29px -10px;" src="/logo_notif.png" width="42" height="121" align="left" hspace="10" /><strong><span style="font-size: 14.0pt; line-height: 107%;">Occupational Health and Safety / Sant&eacute; et s&eacute;curit&eacute; au travail</span></strong></p><p style="margin: 0cm 0cm 8pt; line-height: 107%; font-size: 11pt; font-family: Calibri, sans-serif;">House of Commons / Chambre des communes</p>';
	var str1 = '<p style="margin: 0cm 0cm 8pt; line-height: 107%; font-size: 11pt; font-family: Calibri, sans-serif;">50';
	var str2 = "O'Connor, 8<sup>th 50 rue O'Connor, 8<sup>e</sup>étage<br/>Ottawa, Ontario, K1A 0A6</p>";
	var str3='<p style="margin: 0cm 0cm 8pt; line-height: 107%; font-size: 11pt; font-family: Calibri, sans-serif;"><a style="color: #0563c1; text-decoration: underline;href="mailto:OHS-SST@parl.gc.ca">OHS-SST@parl.gc.ca</a></p>';
	var str4='<p style="margin: 0cm 0cm 8pt; line-height: 107%; font-size: 11pt; font-family: Calibri, sans-serif;">Office: 613- 995-3614</p>';
	template.print(str0+str1+str2+str3+str4);

})(current, template, email, email_action, event);
